{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 공원 내 전동휠·킥보드 탑승 금지가 단순 주의 안내인지 실제 벌금(과태료) 부과 대상인지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제22조제1항은 도시공원에서 법 제49조제1항 및 제2항 각 호의 행위를 하여서는 아니된다고 정하고 있어, 전동휠·킥보드 탑승 금지는 단순 주의 안내가 아니라 금지행위 규정이다. 같은 조례 제23조제1항은 시장이 법 제56조에 따라 과태료를 부과하는 기준을 영 제51조제1항 별표 4와 같다고 정하고 있어, 금지행위 위반 시 과태료 부과 대상이 될 수 있다. 다만 전동휠·킥보드 탑승이 법 제49조제1항 및 제2항 각 호의 금지행위에 해당하는지는 해당 법령 조항과 별표 4의 개별 기준을 확인해야 한다.",
          "b_ids": "도시공원:제22조제1항, 도시공원:제23조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
